export const STATUS={yes:'有',no:'无',partial:'有 · 条件',unknown:'待核实'};
export const clone=x=>JSON.parse(JSON.stringify(x));
export const uid=(prefix='id')=>prefix+'_'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2));
export const safeUrl=u=>{try{let x=new URL(String(u));return ['http:','https:'].includes(x.protocol)?x.href:''}catch{return ''}};
export function normalizeStatus(s){const v=String(s??'').trim().toLowerCase();if(['yes','有','支持','true','✓'].includes(v))return 'yes';if(['no','无','不支持','false','×'].includes(v))return 'no';if(['partial','conditional','有 · 条件','条件支持','部分支持','有条件','有（条件）'].includes(v))return 'partial';if(['unknown','unverified','待核实','未知','?',''].includes(v))return 'unknown';throw Error('无法识别状态“'+s+'”。请使用 有、无、条件支持 或 待核实。')}
export function parseCSV(text){text=text.replace(/^\uFEFF/,'');let rows=[],row=[],cell='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else if(!quote&&cell.trim()){throw Error('CSV 引号位置不正确')}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quote)throw Error('CSV 存在未闭合引号');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows}
const aliases={module:['module','模块','功能模块'],feature:['feature','功能','功能详情','功能点','name'],status:['status','状态','支持状态'],summary:['summary','简介','功能简介'],detail:['detail','详情','说明'],sourceUrl:['sourceurl','来源','来源链接','url'],sourceTitle:['sourcetitle','来源标题'],checkedAt:['checkedat','核验日期','日期'],featureId:['featureid','功能id']};
function fromTable(rows){if(rows.length<2)throw Error('需要表头与至少一条能力记录');const head=rows[0].map(x=>x.trim().toLowerCase());if(!head.some(x=>aliases.feature.includes(x)))throw Error('缺少 feature / 功能 列');if(!head.some(x=>aliases.status.includes(x)))throw Error('缺少 status / 状态 列');return rows.slice(1).map((r,n)=>{let o={};for(let [key,names] of Object.entries(aliases)){let i=head.findIndex(h=>names.includes(h));if(i>=0)o[key]=r[i]?.trim()||''}if(r.length!==head.length)throw Error('第 '+(n+2)+' 行列数与表头不一致');return o})}
export function parseReport(text,filename){if(text.length>2e6)throw Error('报告文本请限制在 2 MB 内');let ext=filename.split('.').pop().toLowerCase();let result;if(ext==='json'){let x;try{x=JSON.parse(text)}catch{throw Error('JSON 格式错误，请检查逗号与引号')}if(x.schemaVersion&&x.products&&x.capabilities&&!Array.isArray(x.capabilities))return {snapshot:x};result=Array.isArray(x)?{capabilities:x}:x}else if(ext==='csv'){result={capabilities:fromTable(parseCSV(text))}}else if(['md','txt'].includes(ext)){let lines=text.split(/\r?\n/).filter(l=>l.trim().startsWith('|'));if(!lines.length)throw Error('当前支持 Markdown 能力表格。自由文本 / PDF / Word 的 AI 语义解析已预留接口，尚未接入。请下载模板后整理为表格。');let rows=lines.map(l=>l.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(x=>x.trim())).filter(r=>!r.every(x=>/^:?-{2,}:?$/.test(x)));result={capabilities:fromTable(rows)}}else throw Error('当前可解析 JSON、CSV、Markdown / TXT 表格。PDF / DOCX 自动解析为后续接口。');if(!result||!Array.isArray(result.capabilities)||!result.capabilities.length)throw Error('报告中缺少 capabilities 数组或记录为空');if(result.capabilities.length>500)throw Error('每份报告最多 500 条能力');result.capabilities=result.capabilities.map((r,i)=>{if(!r||typeof r!=='object'||Array.isArray(r))throw Error('第 '+(i+1)+' 条不是能力对象');let feature=String(r.feature||r.name||'').trim();if(!feature&&!r.featureId)throw Error('第 '+(i+1)+' 条缺少功能名');let sourceUrl=String(r.sourceUrl||'').trim();if(sourceUrl&&!safeUrl(sourceUrl))throw Error('第 '+(i+1)+' 条来源必须是 http(s) 链接');let checkedAt=String(r.checkedAt||'').trim();if(checkedAt&&!/^\d{4}-\d{2}-\d{2}$/.test(checkedAt))throw Error('第 '+(i+1)+' 条日期需为 YYYY-MM-DD');return {featureId:String(r.featureId||''),module:String(r.module||'').trim(),feature,status:normalizeStatus(r.status),summary:String(r.summary||r.detail||'待补充简介').slice(0,500),detail:String(r.detail||r.summary||'').slice(0,5000),sourceUrl,sourceTitle:String(r.sourceTitle||'报告引用来源'),checkedAt}});return result}
export function validateDataset(d){if(!d||d.schemaVersion!==1)throw Error('仅支持 schemaVersion 1');if(typeof d.version!=='string'||typeof d.updatedAt!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d.updatedAt))throw Error('缺少有效的数据版本或更新日期');for(let k of ['products','modules','features','history'])if(!Array.isArray(d[k]))throw Error('数据缺少 '+k);if(!d.capabilities||!d.sources)throw Error('缺少能力或来源');if(d.products.length>30||d.features.length>500||d.modules.length>100)throw Error('数据超出规模限制');for(let key of ['products','modules','features']){let ids=new Set();for(let x of d[key]){if(!x||typeof x.id!=='string'||!x.id||!x.name||ids.has(x.id)||['__proto__','constructor','prototype'].includes(x.id))throw Error(key+' ID 或名称无效 / 重复');ids.add(x.id)}}for(let p of d.products){for(let k of ['name','vendor','edition','scope','intro'])if(typeof p[k]!=='string')throw Error('产品档案缺少 '+k);if(!Array.isArray(p.sources)||p.sources.some(id=>!d.sources[id]))throw Error('产品来源无效')}for(let h of d.history)if(!h||typeof h.action!=='string'||typeof h.description!=='string'||!Number.isFinite(Date.parse(h.at)))throw Error('变更记录无效');for(let f of d.features)if(typeof f.description!=='string'||!['P0','P1','P2'].includes(f.priority))throw Error('功能定义或优先级无效');let modules=new Set(d.modules.map(x=>x.id));for(let f of d.features)if(!modules.has(f.moduleId))throw Error('功能引用了不存在的模块');for(let p of d.products){if(!d.capabilities[p.id])throw Error('产品缺少能力数据');for(let f of d.features){let c=d.capabilities[p.id][f.id];if(!c||!Object.hasOwn(STATUS,c.status)||typeof c.summary!=='string'||typeof c.detail!=='string'||!Array.isArray(c.sourceIds))throw Error('能力数据无效：'+p.id+'/'+f.id);for(let id of c.sourceIds)if(!d.sources[id])throw Error('能力引用来源不存在：'+id)}}for(let s of Object.values(d.sources))if(!s||typeof s.title!=='string'||!safeUrl(s.url))throw Error('来源链接无效');return true}
export function planImport(data,report,productId){if(!data.products.some(p=>p.id===productId))throw Error('请选择目标产品');let seen=new Set();return report.capabilities.map((r,i)=>{let feature=data.features.find(f=>r.featureId&&f.id===r.featureId);if(!feature){let options=data.features.filter(f=>f.name===r.feature);feature=options.find(f=>data.modules.find(m=>m.id===f.moduleId)?.name===r.module)||(options.length===1?options[0]:null)}const module=data.modules.find(m=>m.name===r.module);let key=feature?.id||r.module+'|'+r.feature;if(seen.has(key))throw Error('报告中同一功能重复：'+r.feature);seen.add(key);if(!feature&&!r.module)throw Error('新增功能“'+r.feature+'”缺少 module');if(r.featureId&&!data.features.some(f=>f.id===r.featureId))throw Error('未知 featureId：'+r.featureId+'。新增字段请只填写 module 与 feature。');return {...r,index:i,matchedId:feature?.id||null,moduleId:feature?.moduleId||module?.id||null,change:feature?'更新能力':'新增字段',before:feature?data.capabilities[productId][feature.id]:null}})}
export function applyImport(data,plan,productId,filename){let next=clone(data);for(let r of plan){let moduleId=r.moduleId;if(!moduleId){let m=next.modules.find(x=>x.name===r.module);if(!m){m={id:uid('module'),name:r.module,icon:'▤'};next.modules.push(m)}moduleId=m.id}let fid=r.matchedId;if(!fid){fid=uid('feature');next.features.push({id:fid,moduleId,name:r.feature,description:r.detail||r.summary,priority:'P1'});for(let p of next.products)next.capabilities[p.id][fid]={status:'unknown',summary:'待核实',detail:'新增字段，尚未评估该产品。',sourceIds:[],checkedAt:'',evidence:'待核实'}}let sourceIds=[];if(r.sourceUrl){let sourceId=uid('source');next.sources[sourceId]={url:safeUrl(r.sourceUrl),title:r.sourceTitle,checkedAt:r.checkedAt};sourceIds=[sourceId]}next.capabilities[productId][fid]={status:r.status,summary:r.summary,detail:r.detail||r.summary,sourceIds,checkedAt:r.checkedAt,evidence:'导入报告 · 未独立核验',reportName:filename}}
next.updatedAt=new Date().toISOString().slice(0,10);next.history.unshift({id:uid('change'),at:new Date().toISOString(),action:'导入报告',description:filename+' → '+productId+' · '+plan.length+' 项'});validateDataset(next);return next}
export function matchingFeatures(data,selected,query='',module='all',status='all',onlyDiff=false){let q=query.trim().toLowerCase();return data.features.filter(f=>{if(module!=='all'&&f.moduleId!==module)return false;let cells=selected.map(id=>data.capabilities[id][f.id]);if(status!=='all'&&!cells.some(c=>c.status===status))return false;if(onlyDiff&&(cells.length<2||new Set(cells.map(c=>c.status+'|'+c.summary)).size<2))return false;return !q||[f.name,f.description,data.modules.find(m=>m.id===f.moduleId)?.name,...cells.flatMap(c=>[c.summary,c.detail])].join(' ').toLowerCase().includes(q)})}
